export function findMedianFromDataStream(operations                     )                  {
const a         =[];return operations.map(op=>{if(op[0]==='addNum'){const x=Number(op[1]);let l=0,r=a.length;while(l<r){const m=(l+r)>>1;if(a[m]<x)l=m+1;else r=m;}a.splice(l,0,x);return null;}const n=a.length;return n%2?2*a[n>>1]:a[n/2-1]+a[n/2];});
}

